# Let's check if there's symmetry or relationship between components
# Top pair: comp 0 (color 2) and comp 1 (color 3)
# Bottom pair: comp 2 (color 3) and comp 3 (color 2)

# Check bounding boxes
def bbox(cells):
    rows = [r for r,c in cells]
    cols = [c for r,c in cells]
    return (min(rows), max(rows)+1, min(cols), max(cols)+1)

for i, comp in enumerate(components):
    b = bbox(comp['cells'])
    print(f"Comp {i} (color {comp['color']}): bbox={b}, cells={len(comp['cells'])}")

# Check if shapes are rotations of each other or complementary
# Comp 0 vs Comp 3: both color 2
# Comp 1 vs Comp 2: both color 3

# Let me check if any are rotations of other
def normalize_shape(cells):
    # Get the shape's relative coordinates
    rows = [r for r,c in cells]
    cols = [c for r,c in cells]
    min_r, min_c = min(rows), min(cols)
    return { (r-min_r, c-min_c) for r,c in cells }

def rotate_90_cw(shape):
    # 90 degree clockwise rotation
    # (r, c) -> (c, -r)
    return { (c, -r) for r,c in shape }

def rotate_180(shape):
    return rotate_90_cw(rotate_90_cw(shape))

def rotate_270_cw(shape):
    return rotate_90_cw(rotate_90_cw(shape))

def shape_matches(target, shape, rotation=0):
    if rotation == 0:
        return target == shape
    shape_rot = shape
    for _ in range(rotation):
        shape_rot = rotate_90_cw(shape_rot)
    return target == shape_rot

# Get shapes
shapes = [normalize_shape(comp['cells']) for comp in components]

print("\nChecking if shapes match with rotations:")
for i in range(4):
    for j in range(4):
        if i != j:
            matches = shape_matches(shapes[j], shapes[i], 0)
