    def rotate(cells):
        return {(c, -r) for r,c in cells}

    r0 = frozenset(shape_b)
    r1 = frozenset(rotate(shape_b))
    r2 = frozenset(rotate(r1))
    r3 = frozenset(rotate(r2))

    return shape_a in [r0, r1, r2, r3]

